<script setup>
import { computed, inject, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import RefreshIcon from './RefreshIcon.vue'
import DirectoryTree from './DirectoryTree.vue'
import RegisterWizard from './components/dataobject/RegisterWizard.vue'
import ObjectEditor from './components/dataobject/ObjectEditor.vue'
import SchemaEditor from './components/dataobject/SchemaEditor.vue'
import { objectRequest, objectWrite } from './data-object-api.js'
const can=inject('canPermission',()=>false),directories=ref([]),sources=ref([]),rows=ref([]),total=ref(0),page=ref(1),size=ref(10),selected=ref(0),table=ref(''),name=ref(''),filters=ref({table:'',name:''}),error=ref(''),registerOpen=ref(false),createOpen=ref(false),detail=ref(null),detailOpen=ref(false),edit=ref(false),editForm=ref({}),loading=ref(false),pending=ref([]),pendingOpen=ref(false)
const options=computed(()=>{const build=(parent,depth)=>directories.value.filter(d=>d.parentId===parent).flatMap(d=>[{id:d.id,label:'　'.repeat(depth)+d.name},...build(d.id,depth+1)]);return build(null,0)})
const sourceName=id=>sources.value.find(s=>s.id===id)?.name||`数据源 ${id}`
const schemaOpen=ref(false), schemaObject=ref(null), copyFrom=ref(null), previewRows=ref([]), previewOpen=ref(false), datasets=ref([]), datasetId=ref(null), schemaPending=ref([]), actualFields=ref([]), actualOperation=ref(null), actualOpen=ref(false)
const treeRevision=ref(0)
async function sortDirectories(items){try{await objectWrite('/api/object-directories/sort','POST',{items});await load()}catch(e){await load();error.value=e.message}finally{treeRevision.value++}}
function selectDirectory(id){selected.value=id;page.value=1;loadPage()}
let sequence=0
async function loadPage(){const seq=++sequence;try{const q=new URLSearchParams({table:filters.value.table,name:filters.value.name,page:String(page.value),size:String(size.value)});if(selected.value)q.set('directoryId',String(selected.value));const result=await objectRequest(`/api/data-objects?${q}`);if(seq!==sequence)return;if(page.value>1&&!result.rows.length&&result.total){page.value=Math.ceil(result.total/size.value);return loadPage()}rows.value=result.rows;total.value=result.total}catch(e){if(seq===sequence)error.value=e.message}}
async function load(){try{error.value='';const [dirs,src]=await Promise.all([can('datasource.object_directory.read')?objectRequest('/api/object-directories'):Promise.resolve([]),can('datasource.source.read')?objectRequest('/api/data-sources'):Promise.resolve([])]);directories.value=dirs;sources.value=src;if(can('datasource.object.read'))await loadPage()}catch(e){error.value=e.message}}
function query(){filters.value={table:table.value.trim(),name:name.value.trim()};page.value=1;void loadPage()}
async function directoryAction(command,node){try{if(command==='add'){const r=await ElMessageBox.prompt('输入目录名称','新增目录',{inputPattern:/\S/,inputErrorMessage:'请输入目录名称'});await objectWrite('/api/object-directories','POST',{name:r.value,parentId:node.id||null})}else if(command==='rename'){const r=await ElMessageBox.prompt('输入目录名称','重命名目录',{inputValue:node.name,inputPattern:/\S/});await objectWrite(`/api/object-directories/${node.id}`,'PUT',{name:r.value})}else{await ElMessageBox.confirm(`确定删除目录「${node.name}」？`,'删除目录',{type:'warning'});await objectWrite(`/api/object-directories/${node.id}`,'DELETE');if(selected.value===node.id)selected.value=0}await load();ElMessage.success('操作成功')}catch(e){if(e instanceof Error)error.value=e.message}}
async function show(row,editing=false){try{detail.value=await objectRequest(`/api/data-objects/${row.id}`);datasetId.value=row.datasetId;if(can('datasource.dataset.manage_policy')){try{datasets.value=await objectRequest('/api/datasets')}catch{datasets.value=[]}}edit.value=editing;editForm.value={directoryId:row.directoryId,name:row.name,description:row.description,version:row.version};detailOpen.value=true}catch(e){error.value=e.message}}
async function structure(row){try{schemaObject.value=await objectRequest(`/api/data-objects/${row.id}`);schemaOpen.value=true}catch(e){error.value=e.message}}
async function copy(row){try{copyFrom.value=await objectRequest(`/api/data-objects/${row.id}`);createOpen.value=true}catch(e){error.value=e.message}}
async function previewData(row){try{const d=await objectRequest(`/api/data-objects/${row.id}`);previewRows.value=await objectWrite(`/api/data-objects/${row.id}/preview`,'POST',{fields:[],limit:20});previewOpen.value=true}catch(e){ElMessage.error(e.message)}}
async function bindDataset(){try{await objectWrite(`/api/data-objects/${detail.value.object.id}/dataset`,'PUT',{datasetId:datasetId.value||null});ElMessage.success('数据集关联已更新');await load()}catch(e){ElMessage.error(e.message)}}
async function save(){try{loading.value=true;await objectWrite(`/api/data-objects/${detail.value.object.id}`,'PUT',editForm.value);detailOpen.value=false;await load();ElMessage.success('已保存对象资料')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`确定删除「${row.name}」的对象登记？数据库中的表和数据会保留。`,'删除对象登记',{type:'warning'});await objectWrite(`/api/data-objects/${row.id}`,'DELETE');await load();ElMessage.success('对象登记已删除')}catch(e){if(e instanceof Error)error.value=e.message}}
async function operations(){try{pending.value=can('datasource.object.create_table')?await objectRequest('/api/data-object-operations'):[];schemaPending.value=can('datasource.object.publish_schema')?await objectRequest('/api/data-object-schema-operations'):[];pendingOpen.value=true}catch(e){error.value=e.message}}
async function inspectSchema(item){try{actualFields.value=await objectRequest(`/api/data-object-schema-operations/${item.operationId}/actual`);actualOperation.value=item;actualOpen.value=true}catch(e){ElMessage.error(e.message)}}
async function acknowledgeSchema(){try{await ElMessageBox.confirm('确认已核对以上实际字段？平台将以当前物理结构更新快照，并允许重新编辑。','确认实际结构',{type:'warning'});await objectWrite(`/api/data-object-schema-operations/${actualOperation.value.operationId}/acknowledge`,'POST',{});actualOpen.value=false;await operations();await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function cancelSchema(item){try{await objectWrite(`/api/data-object-schema-operations/${item.operationId}`,'DELETE');await operations()}catch(e){ElMessage.error(e.message)}}
async function recover(item){try{loading.value=true;await objectWrite(`/api/data-object-operations/${item.operationId}/recover`,'POST',{});await operations();await load();ElMessage.success('已重新登记')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
async function resolveAbsent(item){try{await ElMessageBox.confirm('系统将检查目标数据库，只有目标表不存在时才解除待处理状态，不会重新建表。','核对目标表',{type:'warning'});await objectWrite(`/api/data-object-operations/${item.operationId}/resolve-absent`,'POST',{});await operations();ElMessage.success('已确认目标表不存在')}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function cancel(item){try{await objectWrite(`/api/data-object-operations/${item.operationId}`,'DELETE');await operations();ElMessage.success('预览已取消')}catch(e){ElMessage.error(e.message)}}
function exportData(){const q=new URLSearchParams({table:filters.value.table,name:filters.value.name});if(selected.value)q.set('directoryId',String(selected.value));window.location.href=`/api/data-objects/export?${q}`}
onMounted(load)
</script>
<template><section class="objects-page"><el-alert v-if="error" :title="error" type="error" show-icon closable @close="error=''"/><div class="layout"><DirectoryTree :key="treeRevision" :directories="directories" root-label="数据对象目录" :selected="selected" :can-create="can('datasource.object_directory.create')" :can-update="can('datasource.object_directory.update')" :can-delete="can('datasource.object_directory.delete')" @select="selectDirectory" @action="directoryAction" @sort="sortDirectories"/><div class="main"><div class="toolbar list-query-toolbar"><div class="list-query-controls"><el-input v-model="table" placeholder="对象表名" clearable @keyup.enter="query"/><el-input v-model="name" placeholder="对象中文名" clearable @keyup.enter="query"/><el-button type="primary" @click="query">查询</el-button></div><div class="list-query-actions"><el-button v-if="can('datasource.object.create_table')" type="primary" @click="copyFrom=null;createOpen=true">新增</el-button><el-button v-if="can('datasource.object.register')" @click="registerOpen=true">注册</el-button><el-button v-if="can('datasource.object.export')" @click="exportData">导出</el-button><el-button v-if="can('datasource.object.create_table')||can('datasource.object.publish_schema')" @click="operations">操作记录</el-button><el-button class="refresh-button" title="刷新" aria-label="刷新" @click="load"><RefreshIcon/></el-button></div></div><div class="list"><el-table :data="rows" height="100%" empty-text="暂无数据对象"><el-table-column type="index" label="序号" width="70" :index="index=>(page-1)*size+index+1"/><el-table-column label="对象名称" min-width="150"><template #default="s">{{ s.row.identity.table }}</template></el-table-column><el-table-column prop="name" label="对象中文名" min-width="150"/><el-table-column label="数据源" min-width="130"><template #default="s">{{ sourceName(s.row.identity.sourceId) }}</template></el-table-column><el-table-column label="对象目录" min-width="100"><template #default="s">{{directories.find(d=>d.id===s.row.directoryId)?.name||'—'}}</template></el-table-column><el-table-column prop="updatedAt" label="更新时间" min-width="160"/><el-table-column label="模式" min-width="100"><template #default="s">{{ s.row.identity.schema || s.row.identity.catalog || '—' }}</template></el-table-column><el-table-column label="操作" fixed="right" min-width="180"><template #default="s"><el-button v-if="can('datasource.object.preview')" link type="primary" @click="previewData(s.row)">预览</el-button><el-button link type="primary" @click="show(s.row)">查看</el-button><el-button v-if="s.row.identity.type==='TABLE'&&can('datasource.object.publish_schema')" link type="primary" @click="structure(s.row)">字段</el-button><el-button v-if="can('datasource.object.create_table')" link type="primary" @click="copy(s.row)">复制</el-button><el-button v-if="can('datasource.object.update')" link type="primary" @click="show(s.row,true)">编辑</el-button><el-button v-if="can('datasource.object.delete')" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @current-change="loadPage" @size-change="page=1;loadPage()"/></div></div></div>
<RegisterWizard v-model="registerOpen" :sources="sources" :directories="options" :selected-directory="selected" @registered="load"/><ObjectEditor v-model="createOpen" :sources="sources" :directories="options" :selected-directory="selected" :copy-from="copyFrom" @created="load"/><SchemaEditor v-model="schemaOpen" :object="schemaObject" :source="sources.find(s=>s.id===schemaObject?.object.identity.sourceId)" @published="load"/><el-dialog v-model="previewOpen" title="数据预览" width="min(1000px,96vw)"><el-table :data="previewRows" max-height="400"><el-table-column v-for="key in Object.keys(previewRows[0]||{})" :key="key" :prop="key" :label="key" min-width="120"/></el-table></el-dialog>
<el-dialog v-model="detailOpen" :title="edit?'编辑对象资料':'查看数据对象'" width="min(850px,96vw)"><template v-if="detail"><el-form label-position="top"><div class="form-grid"><el-form-item label="对象名称"><el-input :model-value="detail.object.identity.table" disabled/></el-form-item><el-form-item label="对象中文名"><el-input v-model="editForm.name" :disabled="!edit" maxlength="200"/></el-form-item><el-form-item label="对象目录"><el-select v-model="editForm.directoryId" :disabled="!edit"><el-option v-for="d in options" :key="d.id" :label="d.label" :value="d.id"/></el-select></el-form-item><el-form-item label="描述"><el-input v-model="editForm.description" :disabled="!edit" maxlength="1000"/></el-form-item></div></el-form><div v-if="can('datasource.dataset.manage_policy')" class="dataset-binding"><span>预览权限数据集：</span><el-select v-model="datasetId" clearable placeholder="选择相同物理表的数据集"><el-option v-for="d in datasets.filter(x=>x.sourceId===detail.object.identity.sourceId&&x.table===detail.object.identity.table)" :key="d.id" :label="d.name" :value="d.id"/></el-select><el-button @click="bindDataset">保存关联</el-button></div><el-table :data="detail.fields" max-height="350"><el-table-column prop="name" label="字段名"/><el-table-column prop="type" label="原始类型"/><el-table-column prop="length" label="长度"/><el-table-column prop="scale" label="精度"/><el-table-column prop="nullable" label="可空"/><el-table-column prop="primaryKey" label="主键"/><el-table-column prop="remarks" label="注释"/></el-table></template><template #footer><el-button @click="detailOpen=false">关闭</el-button><el-button v-if="edit" type="primary" :loading="loading" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="pendingOpen" title="待处理操作" width="min(850px,96vw)"><el-table :data="pending"><el-table-column label="目标对象"><template #default="s">{{ s.row.identity.catalog }} / {{ s.row.identity.schema }} / {{ s.row.identity.table }}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="200"><template #default="s"><el-button v-if="s.row.status==='PREPARED'" link type="danger" @click="cancel(s.row)">取消预览</el-button><el-button v-if="['EXECUTING','UNKNOWN','NEEDS_REGISTRATION'].includes(s.row.status)&&can('datasource.object.register')" link type="primary" :loading="loading" @click="recover(s.row)">核对并重新登记</el-button><el-button v-if="['EXECUTING','UNKNOWN','NEEDS_REGISTRATION'].includes(s.row.status)" link @click="resolveAbsent(s.row)">核对表不存在</el-button></template></el-table-column></el-table><h4>结构发布操作</h4><el-table :data="schemaPending"><el-table-column prop="objectId" label="对象编号"/><el-table-column prop="status" label="状态"/><el-table-column prop="error" label="说明"/><el-table-column label="操作"><template #default="s"><el-button v-if="s.row.status==='PREPARED'" link @click="cancelSchema(s.row)">取消预览</el-button><el-button v-if="['EXECUTING','UNKNOWN','PARTIAL'].includes(s.row.status)" link type="primary" @click="inspectSchema(s.row)">核对实际结构</el-button></template></el-table-column></el-table></el-dialog><el-dialog v-model="actualOpen" title="核对物理表当前结构" width="min(900px,96vw)"><el-alert title="请核对数据库中的实际字段；确认后平台将同步快照，不会再次执行 SQL。" type="warning" :closable="false"/><el-table :data="actualFields"><el-table-column prop="name" label="字段"/><el-table-column prop="type" label="类型"/><el-table-column prop="length" label="长度"/><el-table-column prop="nullable" label="可空"/><el-table-column prop="primaryKey" label="主键"/></el-table><template #footer><el-button @click="actualOpen=false">关闭</el-button><el-button type="primary" @click="acknowledgeSchema">确认实际结构</el-button></template></el-dialog></section></template>
<style scoped>.objects-page{height:100%;display:flex;flex-direction:column;min-height:0}.layout{display:flex;gap:14px;flex:1;min-height:0}.main{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column}.list{display:flex;flex-direction:column;flex:1;min-height:0;background:#fff}.list .el-pagination{flex:none;padding:12px;justify-content:flex-end}.dataset-binding{display:flex;align-items:center;gap:10px;margin:10px 0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.form-grid .el-select{width:100%}@media(max-width:700px){.layout{flex-direction:column}.form-grid{grid-template-columns:1fr}}</style>
